# WARNING: Under review - generated by LLM.

"""End-to-end semantic/evidence/policy equivalence harness.

Token, page, and latency gains count only when the optimized run preserves
the accepted outcome, the retained evidence, and the policy decisions of the
baseline run.  This harness compares pairs of runs — warm/cold, fork/cold,
compact/full, crash/resume — and reports a structured verdict over three
planes:

- semantic: the final action/outcome and accepted result;
- evidence: durable receipts and tool observations retained;
- policy: approvals, epochs, and effect decisions agree.

Any mismatch fails the pair; the harness never reports a speedup as correct
when the behavior differs.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from .receipts import EffectReceipt
    from .session import SessionLog


@dataclass(frozen=True)
class RunSnapshot:
    """The observable contract of one run, independent of its mechanism."""

    final: str | None
    reason: str
    completed: bool
    tool_actions: tuple[tuple[str, str], ...]
    receipts: tuple[str, ...]
    observations: tuple[str, ...]
    approval_state: str = "unknown"
    world_state: str = "unknown"
    token_accounting: dict[str, int] = field(default_factory=dict)


@dataclass(frozen=True)
class PlaneResult:
    """PASS/FAIL verdict for one equivalence plane."""

    plane: str
    ok: bool
    detail: str = ""


@dataclass(frozen=True)
class EquivalenceReport:
    """The full verdict of comparing a baseline run with an optimized run."""

    baseline: RunSnapshot
    optimized: RunSnapshot
    planes: tuple[PlaneResult, ...]

    @property
    def ok(self) -> bool:
        return all(plane.ok for plane in self.planes)

    def render(self) -> str:
        lines = ["semantic/evidence/policy equivalence: PASS" if self.ok else "FAIL"]
        for plane in self.planes:
            status = "PASS" if plane.ok else "FAIL"
            lines.append(f"- {plane.plane}: {status} ({plane.detail})")
        return "\n".join(lines)


def _receipt_ids(receipts: tuple[EffectReceipt, ...]) -> tuple[str, ...]:
    return tuple(sorted(receipt.receipt_id for receipt in receipts))


def snapshot_run(
    *,
    final: str | None,
    reason: str,
    completed: bool,
    session: "SessionLog | None" = None,
    receipts: tuple[EffectReceipt, ...] = (),
    approval_state: str = "unknown",
    world_state: str = "unknown",
    token_accounting: dict[str, int] | None = None,
) -> RunSnapshot:
    """Capture the observable contract of one run.

    ``session`` supplies the durable event evidence; ``receipts`` supplies the
    canonical effect evidence.  Everything the harness compares is public and
    mechanism-independent.
    """

    tool_actions: list[tuple[str, str]] = []
    observations: list[str] = []
    if session is not None:
        for event in session.events:
            if event.type == "tool_call":
                tool = event.data.get("tool", "?")
                arguments = json.dumps(event.data.get("arguments", {}), sort_keys=True)
                tool_actions.append((tool, arguments))
            elif event.type == "tool_result":
                content = event.data.get("content", "")
                if isinstance(content, str):
                    observations.append(content)
    return RunSnapshot(
        final=final,
        reason=reason,
        completed=completed,
        tool_actions=tuple(tool_actions),
        receipts=_receipt_ids(receipts),
        observations=tuple(observations),
        approval_state=approval_state,
        world_state=world_state,
        token_accounting=dict(token_accounting or {}),
    )


def compare_runs(
    baseline: RunSnapshot,
    optimized: RunSnapshot,
) -> EquivalenceReport:
    """Compare the observable contracts of a baseline and an optimized run.

    Planes compared:
    - semantic: completed/final/reason and the exact tool-action sequence;
    - evidence: durable receipt IDs and tool observations;
    - policy: approval and world state at the end of each run.

    The token/page/latency accounting in each snapshot is reported for
    context but never used to pass a run whose behavior differs.
    """

    semantic_ok = (
        baseline.completed == optimized.completed
        and baseline.final == optimized.final
        and baseline.reason == optimized.reason
        and baseline.tool_actions == optimized.tool_actions
    )
    semantic = PlaneResult(
        "semantic",
        semantic_ok,
        detail=(
            "final/actions match"
            if semantic_ok
            else (
                f"baseline final={baseline.final!r} actions={baseline.tool_actions}; "
                f"optimized final={optimized.final!r} actions={optimized.tool_actions}"
            )
        ),
    )
    evidence_ok = (
        baseline.receipts == optimized.receipts
        and baseline.observations == optimized.observations
    )
    evidence = PlaneResult(
        "evidence",
        evidence_ok,
        detail=(
            "receipts and observations match"
            if evidence_ok
            else (
                f"baseline receipts={baseline.receipts} observations="
                f"{baseline.observations}; optimized receipts={optimized.receipts} "
                f"observations={optimized.observations}"
            )
        ),
    )
    policy_ok = (
        baseline.approval_state == optimized.approval_state
        and baseline.world_state == optimized.world_state
    )
    policy = PlaneResult(
        "policy",
        policy_ok,
        detail=(
            "state matches"
            if policy_ok
            else (
                f"baseline approval={baseline.approval_state} "
                f"world={baseline.world_state}; optimized "
                f"approval={optimized.approval_state} world={optimized.world_state}"
            )
        ),
    )
    return EquivalenceReport(baseline, optimized, (semantic, evidence, policy))
